  agent="Atlas"
  request="file-write"
  risk="medium"
  countdown={18}
  onDecision={(decision) => agent.resume(decision)}
/>

// Drive it from outside with status (pending, approved, denied). Pass onDecision to hear the answer.
// Y, A and N answer while the card has focus, so they never fire on a page the person is only reading.
// Pass autoFocus to focus the card once it is in view, so a gate that appears mid-task is answerable at once.
// The countdown only runs while the card is in view, so an unseen request never denies itself.

import { AgentDiffReview } from "@/components/design-for-ai/agent-diff-review";

<AgentDiffReview
  agent="Atlas"
  title="Round money once, in each currency's own minor unit"
  changes={proposal.files} // [{ path, language?, hunks: [{ id, oldStart, newStart, scope, note?, lines: [{ kind, text }] }] }]
  view="unified"
  onDecisionsChange={(d) => saveDraft(d)}
  onApply={(ids) => agent.applyHunks(ids)} // return a promise for the applying state; reject it to stay in review
/>

// Hunk ids must be unique across the change set: decisions are keyed by them.
// Keyboard: with a hunk focused, A accepts, R rejects or reopens, J and K move between hunks.
// Split view needs about 900px of width; narrower, the same diff reads as unified.
// No virtualisation: keep a review to a few hundred lines, or page it by file.

