// Flat spans from your tracer: parentId links the tree, start and duration are in ms.
const spans: TraceSpan[] = run.spans.map((s) => ({
  id: s.spanId,
  parentId: s.parentSpanId ?? null,
  name: s.name,
  kind: s.attributes["gen_ai.operation"] ? "llm" : s.kind === "tool" ? "tool" : "step",
  start: s.startMs,
  duration: s.endMs - s.startMs,
  model: s.attributes["gen_ai.request.model"],
  tokensIn: s.attributes["gen_ai.usage.input_tokens"],
  tokensOut: s.attributes["gen_ai.usage.output_tokens"],
  cost: s.costUsd,
  input: s.input,
  output: s.output,
}));

<AgentRunTrace
  trace={spans}
